// === Tab: mySketch ===
// Balon parçacıkları.
let particles = [];

// Balon merkezi.
let balloonX = 200;
let balloonY = 220;

// Balon boyutu.
let balloonRadius = 90;

// Patlama kontrolü.
let exploded = false;

function setup() {

  // Çalışma alanı.
  createCanvas(400, 400);
}

function draw() {

  // Arka plan.
  background("skyblue");

  // Balon ipi.
  stroke(255);
  strokeWeight(2);
  line(balloonX, 400, balloonX, balloonY + 85);

  // Patlamadıysa.
  if (!exploded) {

    // Mouse basılı tutuluyorsa
    // sürekli yeni parçalar ekle.
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {

      for (let i = 0; i < 15; i++) {

        // Daha düzgün yuvarlak için
        // açı ve yarıçap sistemi.
        let angle = random(TWO_PI);

        // Kenarlara daha yoğun dağılım.
        let radius =
          sqrt(random()) * balloonRadius;

        // Hedef koordinatlar.
        let targetX =
          balloonX + cos(angle) * radius;

        let targetY =
          balloonY + sin(angle) * radius;

        // Yeni parçacık oluştur.
        particles.push({

          // Başlangıçta random yerden gelsin.
          x: random(width),
          y: random(height),

          // Gideceği yer.
          targetX: targetX,
          targetY: targetY,

          // Daha küçük parçalar.
          size: random(3, 7),

          // Kırmızı tonları.
          r: random(200, 255),
          g: random(20, 60),
          b: random(20, 60),

          exploded: false,

          speedX: 0,
          speedY: 0
        });
      }
    }

    // Yeterince dolunca patlat.
    if (particles.length > 1200) {

      exploded = true;

      // Parçaları etrafa savur.
      for (let p of particles) {

        p.exploded = true;

        p.speedX = random(-12, 12);
        p.speedY = random(-12, 12);
      }
    }
  }

  // Parçacıkları çiz.
  for (let p of particles) {

    // Patlamadıysa hedefe yaklaş.
    if (!p.exploded) {

      p.x = lerp(p.x, p.targetX, 0.06);
      p.y = lerp(p.y, p.targetY, 0.06);
    }

    // Patladıysa dağılsın.
    else {

      p.x += p.speedX;
      p.y += p.speedY;

      // Hafif yer çekimi hissi.
      p.speedY += 0.1;
    }

    // Parçacığı çiz.
    noStroke();

    fill(p.r, p.g, p.b);

    ellipse(
      p.x,
      p.y,
      p.size
    );
  }

  // Parçalar dağıldıysa reset.
  if (exploded) {

    let outside = 0;

    for (let p of particles) {

      if (
        p.x < -50 ||
        p.x > width + 50 ||
        p.y < -50 ||
        p.y > height + 50
      ) {

        outside++;
      }
    }

    // Büyük kısmı gittiyse sıfırla.
    if (outside > particles.length * 0.85) {

      particles = [];
      exploded = false;
    }
  }
}

